    correction: [{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 3</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 3</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">4(b + 3) + 6b = 122</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">4b + 12 + 6b = 122</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">10b + 12 = 122</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">10b = 122 - 12</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 110 : 10 = 11</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 3 = 14</span>"}],
